import type {readUnifiedHistory} from '@/lib/financial-unified-history';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
export function FinancialUnifiedHistory({history}:{history:ReturnType<typeof readUnifiedHistory>}){
 return <section aria-label="Combined migration results"><h3>Invoice and deposit migration results</h3><p>Matching an existing deposit records its source; it does not reduce the guest’s deposit balance.</p><div className="table-wrap"><table><caption>Matched and additional balances (USD)</caption><thead><tr><th>Category</th><th>Matched existing balance</th><th>Additional balance</th></tr></thead><tbody>{(['receivable','prepayment','security'] as const).map(c=><tr key={c}><th>{c==='receivable'?'Receivables':c==='prepayment'?'Prepayments':'Security deposits'}</th><td>{bankCloseMoney(history.matched[c])}</td><td>{bankCloseMoney(history.additional[c])}</td></tr>)}</tbody></table><table><caption>Posted portions of imported balances</caption><thead><tr><th>Source item</th><th>Amount (USD)</th><th>Destination</th><th>Evidence</th></tr></thead><tbody>{history.records.map(r=><tr key={r.id}><td>{r.source}</td><td>{bankCloseMoney(r.amount)}</td><td>{r.kind==='new_opening'?<>Additional balance: {r.id}<br/>Journal: {r.journal}</>:r.kind==='invoice'?<>Original invoice: {r.destination}<br/>Current invoice: {r.currentInvoice}</>:<>Existing deposit: {r.destination}<br/>Match: {r.id}</>}{r.corrections.length>0&&<ol aria-label="Invoice match correction history">{r.corrections.map(c=><li key={c.id}>Version {c.version}: {c.previous} to {c.invoice} — {c.reason} · {c.created} · Actor {c.actor}</li>)}</ol>}</td><td>{r.evidence}</td></tr>)}</tbody></table></div></section>;
}
